\begin{tikzpicture}[line cap=round,line join=round,font=\sffamily\small]
% cell
\draw[thick] (0,0) rectangle (1.2,0.7);
\node at (0.6,0.35) {cell};
\node[font=\bfseries] at (-0.2,0.35) {$-$};
\node[font=\bfseries] at (1.4,0.35) {$+$};
% wires to coil
\draw[thick] (1.2,0.35) -- (2.0,0.35) -- (2.0,1.6);
\draw[thick] (0,0.35) -- (-0.5,0.35) -- (-0.5,1.6) -- (2.0,1.6);
% iron nail
\draw[thick,fill=gray!35] (2.2,1.35) rectangle (5.0,1.85);
\node at (3.6,2.15) {iron nail};
% coil turns
\foreach \x in {2.4,2.7,3.0,3.3,3.6,3.9,4.2} {
  \draw[thick] (\x,1.25) arc (240:-60:0.22 and 0.42);
}
\node at (3.6,0.85) {coil};
% paper clips
\draw[thick] (5.05,1.45) -- (5.45,1.25) -- (5.45,1.65) -- cycle;
\draw[thick] (5.05,1.70) -- (5.40,1.55) -- (5.40,1.90) -- cycle;
\node at (5.9,1.55) {clips};
\end{tikzpicture}
